with source_rows(uai,slug,canonical_name,website_url,source_url) as (values ('0134009M','aix-marseille-universite','Aix-Marseille Université','https://www.univ-amu.fr/','https://www.onisep.fr/ressources/structures-enseignement/provence-alpes-cote-d-azur/bouches-du-rhone/aix-marseille-universite'),('0333298F','universite-de-bordeaux','Université de Bordeaux','https://www.u-bordeaux.fr/','https://www.onisep.fr/ressources/structures-enseignement/nouvelle-aquitaine/gironde/universite-de-bordeaux'),('0673021V','universite-de-strasbourg','Université de Strasbourg','https://www.unistra.fr/','https://www.onisep.fr/ressources/structures-enseignement/grand-est/bas-rhin/universite-de-strasbourg'),('0755890V','sorbonne-universite','Sorbonne Université','https://www.sorbonne-universite.fr/','https://www.sorbonne-universite.fr/actualites/versez-votre-taxe-dapprentissage-sorbonne-universite'),('0912408Y','universite-paris-saclay','Université Paris-Saclay','https://www.universite-paris-saclay.fr/','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/essonne/universite-paris-saclay'),('0756036D','universite-psl','Université PSL','https://psl.eu/','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/paris/universite-paris-sciences-et-lettres-universite-psl'),('0383546Y','universite-grenoble-alpes','Université Grenoble Alpes','https://www.univ-grenoble-alpes.fr/','https://www.onisep.fr/ressources/structures-enseignement/auvergne-rhone-alpes/isere/universite-grenoble-alpes'),('0062205P','universite-cote-dazur','Université Côte d''Azur','https://univ-cotedazur.fr/','https://www.onisep.fr/ressources/structures-enseignement/provence-alpes-cote-d-azur/alpes-maritimes/universite-cote-d-azur'),('0755976N','universite-paris-cite','Université Paris Cité','https://u-paris.fr/','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/paris/universite-paris-cite')) insert into catalog.institutions(id,country_code,canonical_name,institution_type,website_url,status,slug,institution_kind,ownership_type) select md5('fr:uai:'||uai)::uuid,'FR',canonical_name,'university',website_url,'active',slug,'university','public' from source_rows on conflict(country_code,slug) where slug is not null do update set canonical_name=excluded.canonical_name,institution_type=excluded.institution_type,website_url=excluded.website_url,status=excluded.status,institution_kind=excluded.institution_kind,ownership_type=excluded.ownership_type,updated_at=now(); with source_rows(uai,slug,source_url) as (values ('0134009M','aix-marseille-universite','https://www.onisep.fr/ressources/structures-enseignement/provence-alpes-cote-d-azur/bouches-du-rhone/aix-marseille-universite'),('0333298F','universite-de-bordeaux','https://www.onisep.fr/ressources/structures-enseignement/nouvelle-aquitaine/gironde/universite-de-bordeaux'),('0673021V','universite-de-strasbourg','https://www.onisep.fr/ressources/structures-enseignement/grand-est/bas-rhin/universite-de-strasbourg'),('0755890V','sorbonne-universite','https://www.sorbonne-universite.fr/actualites/versez-votre-taxe-dapprentissage-sorbonne-universite'),('0912408Y','universite-paris-saclay','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/essonne/universite-paris-saclay'),('0756036D','universite-psl','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/paris/universite-paris-sciences-et-lettres-universite-psl'),('0383546Y','universite-grenoble-alpes','https://www.onisep.fr/ressources/structures-enseignement/auvergne-rhone-alpes/isere/universite-grenoble-alpes'),('0062205P','universite-cote-dazur','https://www.onisep.fr/ressources/structures-enseignement/provence-alpes-cote-d-azur/alpes-maritimes/universite-cote-d-azur'),('0755976N','universite-paris-cite','https://www.onisep.fr/ressources/structures-enseignement/ile-de-france/paris/universite-paris-cite')) insert into catalog.institution_identifiers(institution_id,identifier_system,identifier_value,source_url) select i.id,'FR_UAI',s.uai,s.source_url from source_rows s join catalog.institutions i on i.country_code='FR' and i.slug=s.slug on conflict(identifier_system,identifier_value) do update set institution_id=excluded.institution_id,source_url=excluded.source_url; create or replace view public.institution_identity_fr_v1 with(security_invoker=true) as select i.id institution_id,i.country_code,i.slug,i.canonical_name,official.identifier_value uai,official.source_url uai_source_url from catalog.institutions i join catalog.institution_identifiers official on official.institution_id=i.id and official.identifier_system='FR_UAI' where i.country_code='FR' and i.status<>'inactive' and i.slug is not null; revoke all on public.institution_identity_fr_v1 from public,anon,authenticated; grant select on public.institution_identity_fr_v1 to service_role; do $$ declare c int; begin select count(*) into c from public.institution_identity_fr_v1; if c<>9 then raise exception 'Expected 9 FR UAI identities, found %',c; end if; select count(*) into c from public.institution_identity_fr_v1 where uai !~ '^[0-9]{7}[A-Z]$'; if c>0 then raise exception 'Invalid FR UAI identities %',c; end if; select count(*) into c from catalog.institutions where country_code='FR' and status<>'inactive' and (institution_kind is distinct from 'university' or ownership_type is distinct from 'public' or website_url !~ '^https://'); if c>0 then raise exception 'Invalid FR institution rows %',c; end if; end $$;;
